(()=>{'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',flag:'M5 22V3m0 0c5-3 9 4 15 0v11c-6 4-10-3-15 0',live:'M12 12h.01M8 8a6 6 0 0 0 0 8m8-8a6 6 0 0 1 0 8M4.5 4.5a11 11 0 0 0 0 15m15-15a11 11 0 0 1 0 15',trophy:'M8 3h8v8a4 4 0 0 1-8 0V3m0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4M12 15v5m-4 1h8',chat:'M21 11a9 9 0 0 1-9 9H4l-2 2V11a9 9 0 0 1 19 0M7 10h10M7 14h6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m14-13a4 4 0 0 1 0 8m4 5v-2a4 4 0 0 0-3-4M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',calendar:'M4 5h16v16H4zM4 10h16M8 3v4m8-4v4M8 14h2m4 0h2m-8 3h2',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0m-5 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',plus:'M12 5v14M5 12h14',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',gear:'m9 3-1 3-3 1-2 3 2 2-1 3 3 1 1 3h4l1-3 3-1 1-3-2-2 1-3-3-1-1-3H9m6 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',user:'M20 21v-2a6 6 0 0 0-6-6h-4a6 6 0 0 0-6 6v2M16 5a4 4 0 1 1-8 0 4 4 0 0 1 8 0',camera:'M3 7h4l2-3h6l2 3h4v14H3V7m13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',video:'M3 5h12v14H3zM15 10l6-4v12l-6-4',send:'m22 2-7 20-4-9L2 9 22 2ZM11 13 22 2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',copy:'M8 8h13v13H8zM16 8V3H3v13h5',logout:'M9 3H3v18h6m0-9h12m-5-5 5 5-5 5',info:'M12 11v6m0-10v.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',cloud:'M6 18a5 5 0 0 1-1-10 7 7 0 0 1 13-1 5 5 0 1 1 0 11M9 14l3-3 3 3m-3-3v10',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12m13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',more:'M5 12h.01M12 12h.01M19 12h.01',smile:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M8 14q4 5 8 0M8 8v.1m8-.1v.1'};
const ico=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.flag}"/></svg>`;
const months=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
let DEMO=!!window.CLUBHOUSE_STATIC||!!window.CLUBHOUSE_DEMO||location.protocol==='file:'||new URLSearchParams(location.search).has('demo');
let S=null,view=location.hash.slice(1)||'home',roundId=null,hole=1,draftScore=4,rankMode='annual',rankMonth=new Date().getMonth(),search='',room='league',messages=[],attachment=null,source=null,connected=false,syncing=false,queue=[],conflict=null,authMode='login',bootstrap=null,installPrompt=null,toastTimer=null,modalFocus=null,refreshTimer=null,loadingState=false,refreshAgain=false;
const user=id=>S?.users.find(x=>x.id===id)||{name:'Jugador',id,hi:0};
const asset=id=>DEMO?Demo.media(id):'/media/'+encodeURIComponent(id);
const avatar=(u,size='')=>`<span class="avatar ${size} a${([...String(u.id)].reduce((a,c)=>a+c.charCodeAt(0),0)%5)}">${u.avatar?`<img src="${esc(asset(u.avatar))}" alt="Foto de ${esc(u.name)}" loading="lazy">`:esc(u.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</span>`;
const brand=()=>`<span class="brand"><span class="brand-mark">${ico('flag')}</span>clubhouse<span class="brand-period">.</span></span>`;
const btn=(text,action,type='primary',extra='')=>`<button type="button" class="btn ${type}" data-action="${action}" ${extra}>${text}</button>`;
const pill=r=>`<span class="badge ${{live:'',submitted:'gold',validated:'',rejected:'red',cancelled:'red'}[r.status]}">${({live:'En juego',submitted:'Por validar',validated:'Validada',rejected:'Para corregir',cancelled:'Cancelada'})[r.status]}</span>`;
const empty=(title,text,action='',label='')=>`<div class="empty">${ico('flag')}<h3>${title}</h3><p>${text}</p>${action?btn(label,action):''}</div>`;
const time=iso=>{const n=Math.max(0,Date.now()-new Date(iso).getTime());return n<60000?'Ahora':n<3600000?`Hace ${Math.floor(n/60000)} min`:n<86400000?`Hace ${Math.floor(n/3600000)} h`:new Date(iso).toLocaleDateString('es-ES',{day:'numeric',month:'short'})};
const toast=(text,error=false)=>{const el=$('#toast');el.textContent=text;el.className='show'+(error?' error':'');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',4200)};
async function api(path,method='GET',data){
 if(DEMO)return Demo.call(path,method,data);
 const res=await fetch(path,{method,credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const result=await res.json();if(!res.ok){if(res.status===401&&S){S=null;source?.close();renderAuth()}throw Object.assign(Error(result.error||'No se ha podido completar la acción.'),{status:res.status,data:result})}return result;
}
function qkey(){return 'clubhouse-queue-'+(DEMO?'demo-':'')+S.me.id}
function persistQueue(){localStorage.setItem(qkey(),JSON.stringify(queue))}
function activeRound(){return S.rounds.find(r=>r.userId===S.me.id&&r.status==='live')}
function annual(){return Golf.ranking(S.users,S.rounds,S.settings)}
function currentMonth(){return Number(S.today.slice(5,7))-1}
function overlayPending(){for(const op of queue){const r=S.rounds.find(r=>r.id===op.roundId);if(r){r.scores[op.hole-1]=op.score;r.revision=Math.max(r.revision,op.revision+1);r.currentHole=Math.min(18,r.scores.findIndex(x=>x===null)+1||18)}}}
async function loadState(render=true){
 if(loadingState){refreshAgain=true;return}loadingState=true;
 try{S=await api('/api/state');localStorage.setItem('clubhouse-cache-'+(DEMO?'demo':'real'),JSON.stringify(S));overlayPending();if(view==='chat')await loadMessages();if(render)renderApp()}catch(e){if(e.status!==401)toast(e.message,true)}finally{loadingState=false;if(refreshAgain){refreshAgain=false;void loadState(render)}}
}
function debounceRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(()=>loadState(!['profile','admin'].includes(view)),150)}
function connect(){
 if(DEMO){connected=true;Demo.subscribe(()=>debounceRefresh());return}
 source?.close();source=new EventSource('/api/events');source.onopen=()=>{connected=true;renderConnection();debounceRefresh();void syncQueue()};source.onerror=()=>{connected=false;renderConnection()};
 source.addEventListener('change',ev=>{const e=JSON.parse(ev.data);if(e.actorId!==S.me.id&&((['hole','started'].includes(e.type)&&(S.me.follows||[]).includes(e.actorId))||(e.type==='chat'&&S.me.notifyChat))){toast(e.text);if(document.hidden&&'Notification'in window&&Notification.permission==='granted')navigator.serviceWorker?.ready.then(sw=>sw.showNotification('Clubhouse',{body:e.text,icon:'/assets/icon-192.png',tag:String(e.id),data:{url:e.roundId?'/?round='+e.roundId:'/?view=chat'}}))}debounceRefresh()});
}
function renderConnection(){const el=$('#connection');if(el)el.innerHTML=`<span class="dot ${connected?'':'red'}"></span>${DEMO?'Demo local':connected?'Conectado':'Reconectando'}`}
async function boot(){
 if(!localStorage.getItem('clubhouse-welcome-v2')){renderWelcome();return}
 try{
  if(DEMO)Demo.init();bootstrap=await api('/api/bootstrap');
  if(DEMO||!bootstrap.setupRequired){try{S=await api('/api/state')}catch(e){if(e.status!==401)throw e}}
  if(!S){renderAuth();return}
  queue=JSON.parse(localStorage.getItem(qkey())||'[]');overlayPending();
  const params=new URLSearchParams(location.search);roundId=params.get('round');if(roundId&&S.rounds.some(r=>r.id===roundId)){view='score';selectHole(S.rounds.find(r=>r.id===roundId).currentHole||1)}else if(params.get('view'))view=params.get('view');
  if(view==='score'&&!roundId)view='home';if(view==='chat')await loadMessages();renderApp();connect();void syncQueue();
 }catch(e){try{S=JSON.parse(localStorage.getItem('clubhouse-cache-'+(DEMO?'demo':'real')));if(S){queue=JSON.parse(localStorage.getItem(qkey())||'[]');overlayPending();renderApp();toast('Sin conexión. Los golpes se guardarán en este dispositivo.');connect();return}}catch{}$('#app').innerHTML=`<div class="loading">${brand()}<p>No se ha podido conectar con el servidor.</p><div class="spacer"></div>${btn('Reintentar','retry','lime')}${btn('Explorar demo','demo','outline')}</div>`}
}
function navItems(){return [['home','home','Inicio'],['play','flag','Jugar'],['ranking','trophy','Liga'],['chat','chat','Club']]}
function renderApp(){
 if(!S||welcomeStage)return;
 const focused=document.activeElement?.id,selection=document.activeElement?.selectionStart,chatDraft=$('#chat-input')?.value,scroll=$('#messages')?.scrollTop,nearBottom=$('#messages')?$('#messages').scrollHeight-$('#messages').scrollTop-$('#messages').clientHeight<70:true;
 const selected=['live','calendar'].includes(view)?'ranking':view==='score'?'play':view==='people'?'chat':view;
 const title={home:'Inicio',play:'Vamos a jugar',ranking:'Tu liga',chat:'El club',live:'En directo',calendar:'Calendario',courses:'Campos',people:'Jugadores',profile:'Mi perfil',admin:'Administrar liga',score:'Mi vuelta'}[view]||'Inicio';
 const nav=()=>navItems().map(([v,i,t])=>`<button data-action="nav" data-view="${v}" class="${selected===v?'active':''}" ${selected===v?'aria-current="page"':''}>${ico(i)}<span>${t}</span></button>`).join('');
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><button data-action="nav" data-view="home" aria-label="Ir al inicio">${brand()}</button><div class="league-tag"><span class="eyebrow">TU LIGA PRIVADA</span><p>${esc(S.settings.name)}</p><small>Temporada ${S.settings.year}</small></div><nav class="nav" aria-label="Principal">${nav()}</nav><div class="sidebar-foot"><button class="profile-button" data-action="nav" data-view="profile">${avatar(S.me)}<span>${esc(S.me.name)}<small>Hándicap ${S.me.hi}</small></span></button><button class="link" data-action="more-menu">${ico('gear')} Más opciones</button></div></aside><main class="main"><header class="topbar"><span class="desktop-title">${title}</span><span class="mobile-brand">${brand()}</span><div class="right"><span class="status" id="connection"></span><button class="icon-btn" data-action="notifications" aria-label="Actividad y notificaciones">${ico('bell')}</button><button data-action="nav" data-view="profile" aria-label="Mi perfil">${avatar(S.me)}</button></div></header>${DEMO?`<div class="demo-bar"><span>VISTA PREVIA · Datos ficticios, guardados en este navegador</span><button data-action="restart-journey">Desde el inicio</button></div>`:''}${queue.length?`<div class="sync-bar">${ico('cloud')} ${queue.length} hoyo${queue.length>1?'s':''} pendiente${queue.length>1?'s':''}. ${conflict?'<button data-action="resolve-conflict"><u>Revisar conflicto</u></button>':!navigator.onLine?'Se enviarán cuando vuelva la cobertura.':'Guardando…'}</div>`:''}<div class="content">${({home:homePage,play:playPage,live:livePage,ranking:rankingPage,chat:chatPage,calendar:calendarPage,courses:coursesPage,people:peoplePage,profile:profilePage,admin:adminPage,score:scorePage}[view]||homePage)()}</div></main><nav class="mobile-nav" aria-label="Navegación móvil">${nav()}</nav></div>`;
 renderConnection();
 if(chatDraft!==undefined&&$('#chat-input'))$('#chat-input').value=chatDraft;
 if($('#messages')){const m=$('#messages');m.scrollTop=nearBottom?m.scrollHeight:(scroll||0)}
 if(focused&&$('#'+focused)){const el=$('#'+focused);el.focus({preventScroll:true});if(selection!==null&&el.setSelectionRange)try{el.setSelectionRange(selection,selection)}catch{}}
}
function heading(title,sub,action=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function liveCard(r){const u=user(r.userId),s=Golf.summary(r);return `<button class="card live-card" data-action="round" data-id="${r.id}"><div class="top">${avatar(u)}<span class="live-pill"><span class="dot live"></span>EN JUEGO</span></div><div class="live-name">${esc(u.name)}</div><p class="live-course">${esc(r.course.name)} · ${esc(r.course.tee)}</p><div class="live-numbers"><div><span class="pts">${s.points}</span> <small>PTS STABLEFORD</small></div><div class="hole"><small>JUGANDO</small><br>Hoyo <b>${r.currentHole}</b></div></div><div class="progress">${r.scores.map((x,i)=>`<span class="${x!==null?'done':i+1===r.currentHole?'current':''}"></span>`).join('')}</div></button>`}
function rankRow(r){return `<div class="rank-row ${r.user.id===S.me.id?'me':''}"><span class="pos">${r.rank===1?'♔':r.rank}</span>${avatar(r.user)}<span class="player">${esc(r.user.name)}${r.user.id===S.me.id?' <small style="display:inline">(tú)</small>':''}<small>${r.entries} jornadas · HCP ${r.user.hi}</small></span><span class="total">${r.total}<span class="pts-label">PTS</span></span></div>`}
function activity(e){return `<button class="activity-item" style="text-align:left;width:100%" data-action="${e.roundId?'round':'notifications'}" ${e.roundId?`data-id="${e.roundId}"`:''}><span class="activity-symbol">${ico({hole:'flag',started:'live',chat:'chat',round:'trophy',joined:'users',course:'pin'}[e.type]||'check')}</span><span><p>${esc(e.text)}</p><small>${time(e.time)}</small></span></button>`}
function homePage(){
 const own=activeRound(),live=S.rounds.filter(r=>r.status==='live'&&r.userId!==S.me.id),ranking=annual(),me=ranking.find(r=>r.user.id===S.me.id),month=currentMonth(),pending=S.rounds.filter(r=>r.status==='submitted'&&r.userId!==S.me.id&&(r.markerId===S.me.id||S.me.role==='admin'));
 return `<div class="greeting"><span class="eyebrow">${months[month]} · JORNADA ${month+1} DE 12</span><h1>Hola, ${esc(S.me.name.split(' ')[0])} <span class="hello-dot"></span></h1><p>Un buen día para una buena vuelta.</p></div><section class="play-banner"><div class="play-banner-copy"><span class="eyebrow">${own?'TU VUELTA SIGUE AQUÍ':'TU PRÓXIMA VUELTA'}</span><h2>${own?'Nos vemos en el hoyo '+own.currentHole:'¿Salimos a jugar?'}</h2><p>${own?esc(own.course.name)+' · '+Golf.summary(own).points+' puntos por ahora':'Elige campo. Nosotros llevamos la cuenta.'}</p>${btn((own?'Continuar mi vuelta':'Empezar una vuelta')+' '+ico('arrow'),own?'my-round':'new-round','primary')}</div><div class="banner-green" aria-hidden="true"><span class="green-inner"></span><span class="sand"></span><span class="flag-pole"></span><span class="golf-ball"></span></div></section><section class="league-strip"><div class="league-strip-title"><span class="league-icon">${ico('trophy')}</span><div><small>TU TEMPORADA</small><b>${esc(S.settings.name)}</b></div></div><div class="league-metrics"><span><b>${me?.entries?'#'+me.rank:'—'}</b><small>Posición</small></span><span><b>${me?.total||0}</b><small>Puntos</small></span><span><b>${me?.monthly[month]??'—'}</b><small>Este mes</small></span></div><button class="icon-btn" data-action="nav" data-view="ranking" aria-label="Ver clasificación">${ico('arrow')}</button></section>${pending.length?`<button class="pending-callout" data-action="round" data-id="${pending[0].id}">${ico('check')} Tienes ${pending.length} tarjeta${pending.length>1?'s':''} por validar ${ico('arrow')}</button>`:''}<section><div class="section-head"><h2>Amigos en el campo <span class="live-count">${live.length}</span></h2><button class="link" data-action="nav" data-view="live">Ver todos ${ico('arrow')}</button></div>${live.length?`<div class="live-grid">${live.slice(0,3).map(liveCard).join('')}</div>`:`<div class="card">${empty('Hoy puedes abrir el campo','Cuando tus amigos jueguen, sus vueltas aparecerán aquí.')}</div>`}</section><section class="home-bottom"><div><div class="section-head"><h2>Así va la liga</h2><button class="link" data-action="nav" data-view="ranking">Clasificación</button></div><div class="card card-pad">${ranking.slice(0,3).map(rankRow).join('')}</div></div><div><div class="section-head"><h2>Mientras, en el club</h2><button class="link" data-action="nav" data-view="chat">Entrar ${ico('arrow')}</button></div><div class="card card-pad">${S.events.slice(0,3).map(activity).join('')||empty('Todo por compartir','Aquí verás las novedades de tu liga.')}</div></div></section>`;
}
function playPage(){const own=activeRound();return heading('Tu siguiente hoyo empieza aquí.','18 hoyos. Tu hándicap aplicado. Y tus amigos contigo.')+`<section class="play-banner"><div class="play-banner-copy"><span class="eyebrow">${own?'EN JUEGO':'STABLEFORD INDIVIDUAL'}</span><h2>${own?esc(own.course.name):'Tú juega. Nosotros sumamos.'}</h2><p>${own?'Hoyo '+own.currentHole+' · '+Golf.summary(own).points+' puntos':'Campo, barras y marcador. Listo para el primer tee.'}</p>${btn((own?'Continuar vuelta':'Preparar mi vuelta')+' '+ico('arrow'),own?'my-round':'new-round')}</div><div class="banner-green" aria-hidden="true"><span class="green-inner"></span><span class="flag-pole"></span><span class="golf-ball"></span></div></section><div class="quick-links">${[['courses','pin','Ver campos'],['live','live','Seguir una vuelta'],['profile','user','Mis tarjetas']].map(([v,i,t])=>`<button class="card" data-action="nav" data-view="${v}">${ico(i)}<span>${t}</span>${ico('arrow')}</button>`).join('')}</div><div class="note">${ico('cloud')} Sin cobertura, tus golpes quedan guardados en este móvil. Se enviarán cuando vuelva la conexión y abras la app.</div>`}

function livePage(){const live=S.rounds.filter(r=>r.status==='live'),recent=S.rounds.filter(r=>['validated','submitted','rejected'].includes(r.status)).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12);return heading('En directo.','Sigue las vueltas de tus amigos, hoyo a hoyo.',btn(ico('plus')+'Salir a jugar','new-round'))+(live.length?`<div class="round-grid">${live.map(liveCard).join('')}</div>`:`<div class="card">${empty('Nadie en el tee, de momento','Los golpes aparecerán aquí al registrarlos. Puedes seguir a tus amigos para recibir sus avisos.','new-round','Empezar una vuelta')}</div>`)+`<div class="spacer"></div><div class="section-head"><h2>Últimas tarjetas</h2></div><div class="card table-wrap"><table><thead><tr><th>Jugador</th><th>Campo y barras</th><th>Fecha</th><th>Puntos</th><th>Estado</th><th></th></tr></thead><tbody>${recent.map(r=>`<tr><td class="player-cell">${avatar(user(r.userId))}${esc(user(r.userId).name)}</td><td>${esc(r.course.name)}<small style="display:block">${esc(r.course.tee)}</small></td><td>${r.date.slice(8)}/${r.date.slice(5,7)}</td><td class="number">${Golf.summary(r).points}</td><td>${pill(r)}</td><td>${btn('Ver tarjeta','round','outline small',`data-id="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6">Aún no hay tarjetas finalizadas.</td></tr>'}</tbody></table></div>`}
function rankingPage(){const ranks=Golf.ranking(S.users,S.rounds,S.settings,rankMode==='monthly'?rankMonth:null).filter(r=>r.user.name.toLocaleLowerCase().includes(search.toLocaleLowerCase()));return heading('Tu liga.','La mejor vuelta validada de cada mes cuenta.',btn(ico('download')+'Exportar','export-ranking','outline'))+`<div class="secondary-nav">${btn('Clasificación','nav','primary small','data-view="ranking"')}${btn('En directo','nav','outline small','data-view="live"')}${btn('Calendario','nav','outline small','data-view="calendar"')}${btn('Cómo se puntúa','rules','ghost small')}</div><div class="toolbar"><div class="tabs"><button data-action="rank-mode" data-mode="annual" class="${rankMode==='annual'?'active':''}">General ${S.settings.year}</button><button data-action="rank-mode" data-mode="monthly" class="${rankMode==='monthly'?'active':''}">Por jornada</button></div><input id="rank-search" class="search" type="search" placeholder="Buscar jugador…" value="${esc(search)}" aria-label="Buscar jugador"></div>${rankMode==='monthly'?`<div class="chip-row rank-months">${months.map((m,i)=>`<button class="chip ${rankMonth===i?'active':''}" data-action="rank-month" data-month="${i}">${m}</button>`).join('')}</div>`:''}<div class="card ranking-list"><div class="ranking-labels"><span>POS.</span><span>JUGADOR</span><span>PUNTOS</span></div>${ranks.map(r=>`<details class="rank-detail ${r.user.id===S.me.id?'is-me':''}"><summary class="rank-row"><span class="pos">${r.entries?r.rank:'—'}</span>${avatar(r.user)}<span class="player">${esc(r.user.name)}${r.user.id===S.me.id?' <small style="display:inline">(tú)</small>':''}<small>HCP ${r.user.hi} · ${rankMode==='annual'?r.entries+' jornadas':r.entries?'Vuelta validada':'Sin resultado'}</small></span><span class="total">${r.total}<span class="pts-label">PTS</span></span>${ico('plus')}</summary><div class="rank-breakdown"><div class="rank-breakdown-head"><b>${rankMode==='annual'?'Sus jornadas':'Resultado de '+months[rankMonth]}</b>${btn('Ver perfil','player','ghost small',`data-id="${r.user.id}"`)}</div><div class="monthly-breakdown">${r.monthly.map((v,i)=>`<span class="${i===currentMonth()?'current':''}"><small>${months[i].slice(0,3)}</small><b>${v??'—'}</b></span>`).join('')}</div></div></details>`).join('')||empty('No hay coincidencias','Prueba con otro nombre.')}<div class="rank-info">Mejor vuelta validada de cada mes · Suman las ${S.settings.bestMonths} mejores jornadas · Los empates comparten posición.</div></div><div class="note">${ico('info')} Toca un jugador para desplegar sus jornadas. Los resultados en directo son provisionales hasta que su marcador los valide.</div>`}

function calendarPage(){return heading('12 meses. 12 oportunidades.','Juega donde quieras. Tu mejor vuelta del mes es la que cuenta.',btn('Reglas de la liga','rules','outline'))+`<div class="calendar-grid">${months.map((m,i)=>{const rs=Golf.ranking(S.users,S.rounds,S.settings,i),top=rs.filter(r=>r.entries&&r.rank===1),count=S.rounds.filter(r=>r.status==='validated'&&r.date.startsWith(S.settings.year+'-'+String(i+1).padStart(2,'0'))).length;return `<button class="card month-card ${i===currentMonth()?'current':''}" data-action="rank-month" data-month="${i}"><div class="row justify"><span class="month-num">${String(i+1).padStart(2,'0')}</span>${i===currentMonth()?'<span class="badge">En curso</span>':S.settings.openMonths.includes(i+1)?'<span class="badge gold">Reabierta</span>':''}</div><h3>${m}</h3><small class="small-text">${count} vueltas validadas</small>${top.length?`<div class="winner">${avatar(top[0].user)}<span>${esc(top[0].user.name)}${top.length>1?' + '+(top.length-1):''} <b>· ${top[0].total} pts</b></span></div>`:'<p class="small-text muted" style="margin-top:18px">La historia está por escribir.</p>'}</button>`}).join('')}</div>`}
function coursesPage(){return heading('Tu próximo tee.','Cada campo, con sus barras y su tarjeta de 18 hoyos.',btn(ico('plus')+'Añadir campo','add-course'))+`<div class="course-grid">${S.courses.map(c=>`<article class="card course-card"><div class="course-art"><span class="badge ${c.verified?'':'gold'}">${ico(c.verified?'check':'info')}${c.verified?'Barras verificadas':'Por verificar'}</span></div><div class="card-pad"><h3>${esc(c.name)}</h3><p>${esc(c.city)} · ${esc(c.tee)}</p><div class="course-meta"><span><b>${c.pars.reduce((a,b)=>a+b,0)}</b><small>PAR</small></span><span><b>${c.slope}</b><small>SLOPE</small></span><span><b>${c.rating}</b><small>VALOR DE CAMPO</small></span><span><b>${c.meters.reduce((a,b)=>a+b,0)}</b><small>METROS</small></span></div><div class="actions">${btn('Ver tarjeta','course-details','outline small',`data-id="${c.id}"`)}${c.verified?btn('Jugar aquí','new-round','primary small',`data-course="${c.id}"`):S.me.role==='admin'?btn('Verificar','approve-course','primary small',`data-id="${c.id}"`):''}</div></div></article>`).join('')||`<div class="card" style="grid-column:1/-1">${empty('Cualquier campo puede ser vuestro campo','Añade su tarjeta oficial: par, índice de dificultad, distancias, slope y valor de campo para las barras elegidas. El administrador debe comprobarlos.','add-course','Añadir primer campo')}</div>`}</div><div class="note">Cada combinación campo + barras tiene su propio registro. Los datos se introducen desde la tarjeta del club; la app no los descarga de una federación.</div>`}
function peoplePage(){const ranks=annual();return heading('La buena compañía.','Los de siempre. Y los que siempre dicen «una más».',S.me.role==='admin'?btn(ico('copy')+'Invitar al grupo','invite','outline'):'')+`<div class="toolbar"><input id="people-search" class="search" type="search" value="${esc(search)}" placeholder="Buscar en el grupo…" aria-label="Buscar jugador"><small>${S.users.filter(u=>u.active).length} / 30 jugadores</small></div><div class="people-grid">${S.users.filter(u=>u.active&&u.name.toLocaleLowerCase().includes(search.toLocaleLowerCase())).map(u=>{const r=ranks.find(r=>r.user.id===u.id),isMe=u.id===S.me.id;return `<article class="card player-card">${avatar(u,'lg')}<h3>${esc(u.name)}${isMe?' <small>(tú)</small>':''}</h3><p>${esc(u.club||'Sin club favorito')}</p><div class="bio">${esc(u.bio||'Un buen día para jugar al golf.')}</div><div class="line"><span><strong>${u.hi}</strong><small>ÍNDICE HCP</small></span><span><strong>${r?.total||0}</strong><small>PTS LIGA</small></span></div>${btn(isMe?'Mi perfil':(S.me.follows||[]).includes(u.id)?ico('check')+'Siguiendo':ico('plus')+'Seguir',isMe?'nav':'follow','outline small',isMe?'data-view="profile"':`data-id="${u.id}"`)} ${!isMe?btn('Ver','player','ghost small',`data-id="${u.id}"`):''}</article>`}).join('')}</div>`}
async function loadMessages(){const r=await api('/api/messages?room='+encodeURIComponent(room));messages=r.messages}
function chatPage(){const rooms=S.rounds.filter(r=>r.status!=='cancelled').sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,25),r=S.rounds.find(r=>r.id===room),roomName=room==='league'?'El hoyo 19':r?user(r.userId).name+' · '+r.course.name:'Chat de la partida';return heading('El club.','El grupo, dentro y fuera del campo.',btn(ico('users')+'Jugadores','nav','outline','data-view="people"'))+`<div class="card chat-layout"><aside class="chat-rooms"><h3 style="font-size:12px;margin:2px 8px 18px">CONVERSACIONES</h3><button class="chat-room ${room==='league'?'active':''}" data-action="chat-room" data-room="league"><span class="room-icon">${ico('chat')}</span><span><span class="title">El hoyo 19</span><small>Todo el grupo</small></span></button>${rooms.map(r=>`<button class="chat-room ${room===r.id?'active':''}" data-action="chat-room" data-room="${r.id}"><span class="room-icon">${ico('flag')}</span><span><span class="title">${esc(user(r.userId).name)} · ${esc(r.course.name)}</span><small>${r.status==='live'?'● En juego':r.date}</small></span></button>`).join('')}</aside><section class="chat-pane"><div class="chat-header"><div><h3>${esc(roomName)}</h3><small>${room==='league'?S.users.filter(u=>u.active).length+' jugadores · chat de la liga':'Visible para el grupo · fotos, clips y comentarios'}</small></div>${r?btn('Tarjeta','round','outline small',`data-id="${r.id}"`):btn(ico('bell'),'enable-notifications','ghost small','aria-label="Activar avisos"')}</div><div class="messages" id="messages">${messages.length===60?'<button class="link" data-action="older-messages">Cargar mensajes anteriores</button>':''}${messages.map(messageHTML).join('')||empty('El grupo tiene la palabra','Abre conversación, celebra un buen hoyo o comparte una foto desde el campo.')}</div><form id="chat-form" class="composer">${attachment?`<div class="attachment">${ico(attachment.mime?.startsWith('video/')?'video':'camera')} ${esc(attachment.name||'Adjunto listo')}<button type="button" data-action="remove-attachment" aria-label="Quitar adjunto">${ico('close')}</button></div>`:''}<button type="button" class="icon-btn" data-action="attach-photo" aria-label="Tomar o adjuntar foto">${ico('camera')}</button><button type="button" class="icon-btn" data-action="attach-video" aria-label="Grabar o adjuntar clip de vídeo">${ico('video')}</button><textarea id="chat-input" name="text" maxlength="2000" placeholder="Se comenta en el club…" rows="1" aria-label="Mensaje"></textarea><button class="icon-btn send" type="submit" aria-label="Enviar mensaje">${ico('send')}</button></form></section></div><p class="small-text muted" style="margin-top:12px">Fotos hasta 8 MB · Clips MP4, MOV o WebM hasta 25 MB · Se comparten al terminar de subir. ${DEMO?'La demo admite adjuntos de hasta 2 MB.':''}</p>`}
function messageHTML(m){const own=m.userId===S.me.id;return `<div class="message ${own?'mine':''}">${avatar(user(m.userId))}<div class="bubble"><div class="sender">${esc(user(m.userId).name)}</div>${m.media?(m.mime?.startsWith('video/')?`<video src="${esc(asset(m.media))}" controls preload="metadata" playsinline aria-label="Vídeo compartido"></video>`:`<a href="${esc(asset(m.media))}" target="_blank" rel="noopener"><img src="${esc(asset(m.media))}" alt="Foto compartida por ${esc(user(m.userId).name)}" loading="lazy"></a>`):''}<p>${esc(m.text)}</p><div class="row justify"><button class="reaction ${m.reactions.includes(S.me.id)?'on':''}" data-action="react" data-id="${m.id}" aria-label="Me gusta">♡ ${m.reactions.length||''}</button><span class="time">${new Date(m.createdAt).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}${(own||S.me.role==='admin')?` <button type="button" data-action="delete-message" data-id="${m.id}" aria-label="Eliminar mensaje">×</button>`:''}</span></div></div></div>`}
function profilePage(){const me=S.me,ranks=annual(),rank=ranks.find(r=>r.user.id===me.id),myRounds=S.rounds.filter(r=>r.userId===me.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),best=Math.max(0,...myRounds.filter(r=>r.status==='validated').map(r=>Golf.summary(r).points));return heading('Tu juego. Tu historia.','Un perfil a tu altura. Y un hándicap al día.',btn(ico('logout')+'Salir','logout','outline'))+`${DEMO?`<div class="secondary-nav">${btn('Cambiar jugador','demo-switch','outline small')}${btn('Reiniciar demo','demo-exit','ghost small')}${btn('Repetir bienvenida','restart-journey','ghost small')}</div>`:''}<div class="secondary-nav">${btn('Más opciones','more-menu','outline small')}${S.me.role==='admin'?btn('Gestionar liga','nav','outline small','data-view="admin"'):''}</div><div class="profile-grid"><aside><div class="card profile-summary">${avatar(me,'xl')}<h2>${esc(me.name)}</h2><small>${esc(me.club||'Tu club favorito, pendiente')}</small><p class="bio">${esc(me.bio||'Cada hoyo cuenta.')}</p><div class="row" style="justify-content:center;gap:30px"><span><h2>${rank?.entries?'#'+rank.rank:'—'}</h2><small>EN LA LIGA</small></span><span><h2>${best||'—'}</h2><small>MEJOR VUELTA</small></span></div><div class="progress-chart">${rank.monthly.map((p,i)=>`<div class="chart-bar ${i===currentMonth()?'current':''}" style="height:${p===null?4:Math.max(8,p/55*100)}%"><span>${months[i][0]}</span>${p!==null?`<b>${p}</b>`:''}</div>`).join('')}</div><div class="spacer"></div>${btn(ico('camera')+'Cambiar foto','avatar-upload','outline small')}</div><div class="note">${me.hiVerified?'✓ Índice confirmado por el administrador.':'Tu índice está pendiente de confirmación. Pide al administrador que lo revise para poder empezar una vuelta.'}</div></aside><section><form class="card card-pad" id="profile-form"><h3 style="margin-bottom:20px">Así te ve el grupo</h3><div class="row" style="margin-bottom:20px">${avatar(me,'lg')}${btn(ico('camera')+'Cambiar foto','avatar-upload','outline small')}</div><div class="form-grid"><label>Nombre<input name="name" value="${esc(me.name)}" required maxlength="60"></label><label>Índice de hándicap (WHS)<input name="hi" type="number" step="0.1" min="-10" max="54" value="${me.hi}" required><small>Para hándicap +2, escribe −2.</small></label><label class="wide">Tu club o ciudad<input name="club" value="${esc(me.club)}" maxlength="100" placeholder="¿Dónde sueles jugar?"></label><label class="wide">Sobre ti<textarea name="bio" maxlength="240" placeholder="Tu swing en una frase…">${esc(me.bio)}</textarea></label><label class="wide inline-check"><input name="notifyChat" type="checkbox" ${me.notifyChat?'checked':''}>Recibir avisos de mensajes del grupo</label></div><p class="small-text muted" style="margin-bottom:18px">Si cambias tu índice, el administrador debe confirmarlo. Las vueltas ya iniciadas conservan el hándicap con el que saliste.</p><button class="btn primary" type="submit">Guardar mi perfil</button></form><div class="spacer"></div><div class="card card-pad"><div class="section-head"><h3>Clubhouse, en tu móvil</h3>${ico('bell')}</div><p class="small-text muted" style="margin-bottom:15px">Instala la app y activa avisos de los jugadores que sigues. ${S.pushPublicKey?'Web Push está disponible.':'Los avisos con la app cerrada requieren configurar Web Push en el servidor.'}</p><div class="row wrap">${btn(ico('download')+'Instalar app','install','outline')}${btn(ico('bell')+'Activar avisos','enable-notifications','outline')}${btn('Desactivar avisos','disable-notifications','ghost small')}${btn('Cambiar contraseña','password','ghost small')}</div></div></section></div><div class="spacer"></div><div class="section-head"><h2>Mis tarjetas</h2></div><div class="card table-wrap"><table><thead><tr><th>Campo</th><th>Fecha</th><th>HCP juego</th><th>Puntos</th><th>Estado</th><th></th></tr></thead><tbody>${myRounds.slice(0,50).map(r=>`<tr><td>${esc(r.course.name)}</td><td>${r.date}</td><td>${r.playingHandicap}</td><td class="number">${Golf.summary(r).points}</td><td>${pill(r)}</td><td>${btn('Ver','round','outline small',`data-id="${r.id}"`)}</td></tr>`).join('')||'<tr><td colspan="6">Tu primera tarjeta está por empezar.</td></tr>'}</tbody></table></div>`}
function adminPage(){if(S.me.role!=='admin')return empty('Solo administradores','Pide al administrador los cambios que necesites.');return heading('El club, a tu manera.','Reglas claras. Datos revisados. Buen golf.')+`<div class="settings-grid"><section><form class="card card-pad" id="settings-form"><h3 style="margin-bottom:21px">Reglamento de temporada</h3><label>Nombre de la liga<input name="name" value="${esc(S.settings.name)}" maxlength="80" required></label><div class="form-grid"><label>Temporada<input name="year" type="number" value="${S.settings.year}" min="2020" max="2100" required></label><label>Jornadas que suman<select name="bestMonths">${Array.from({length:12},(_,i)=>`<option ${i+1===S.settings.bestMonths?'selected':''}>${i+1}</option>`).join('')}</select></label><label>Porcentaje de hándicap<select name="allowance"><option value="95" ${S.settings.allowance===95?'selected':''}>95 % · individual Stableford</option><option value="100" ${S.settings.allowance===100?'selected':''}>100 %</option></select></label><label>Formato<input disabled value="18 hoyos · Mejor vuelta del mes"></label></div><label>Reabrir jornadas pasadas (opcional)</label><div class="chip-row wrap" style="margin-bottom:20px">${months.map((m,i)=>`<label class="inline-check" style="font-size:10px;margin:3px"><input type="checkbox" name="openMonth" value="${i+1}" ${S.settings.openMonths.includes(i+1)?'checked':''}>${m.slice(0,3)}</label>`).join('')}</div><p class="small-text muted" style="margin-bottom:18px">Por defecto solo se inicia en el mes actual. Los cambios de porcentaje se aplican a nuevas vueltas. Cambiar el año muestra otra temporada sin borrar el histórico.</p><button class="btn primary">Guardar reglas</button></form><div class="spacer"></div><div class="card card-pad"><h3>Invitación privada · 30 plazas</h3><p class="small-text muted" style="margin-top:9px">Cada jugador crea su cuenta con este código. Compártelo junto con la dirección de la app.</p><div class="invite"><span>${esc(S.admin.inviteCode)}</span><button data-action="invite" aria-label="Copiar invitación">${ico('copy')}</button></div>${btn('Renovar código','rotate-invite','outline small')}<div class="note">${S.admin.pushConfigured?'✓ Web Push configurado.':'Web Push pendiente de configurar. Las claves se generan siguiendo la guía del ZIP.'}</div>${btn(ico('download')+'Exportar datos de la liga','admin-export','outline small')}<p class="small-text muted" style="margin-top:10px">La exportación no incluye contraseñas ni los archivos multimedia. La copia completa se realiza con npm run backup.</p></div></section><section class="card card-pad"><div class="section-head"><h3>Jugadores e índices</h3><span class="badge">${S.users.filter(u=>u.active).length}/30</span></div>${S.users.map(u=>`<div class="member-admin">${avatar(u)}<div class="info"><b class="small-text">${esc(u.name)} ${!u.active?'· inactivo':''}</b><small>HCP ${u.hi} · ${u.hiVerified?'confirmado':'pendiente'}${u.role==='admin'?' · admin':''}</small></div>${btn(u.hiVerified?'Revisar':'Confirmar','verify-user',u.hiVerified?'outline small':'primary small',`data-id="${u.id}"`)}</div>`).join('')}<div class="note">Confirma el índice declarado frente a la información del jugador. No hay conexión automática con la RFEG ni se actualiza el índice oficial.</div></section></div>`}
function scorePage(){const r=S.rounds.find(r=>r.id===roundId);if(!r)return empty('No encontramos esa tarjeta','Vuelve al club para elegir otra vuelta.','home','Volver al club');const own=r.userId===S.me.id,editable=own&&r.status==='live',s=Golf.summary(r),i=hole-1,received=Golf.strokes(r.playingHandicap,r.course.si[i]),preview=Golf.points(draftScore,r.course.pars[i],received),canValidate=r.status==='submitted'&&!own&&(r.markerId===S.me.id||S.me.role==='admin');return `<button class="back-link" data-action="nav" data-view="live">${ico('back')} Volver al campo</button>`+heading(`${esc(r.course.name)}<span style="color:#98a77b">.</span>`,`${esc(r.course.tee)} · ${r.date} · ${esc(user(r.userId).name)}`,btn(ico('chat')+'Chat de la partida','round-chat','outline',`data-id="${r.id}"`))+`<div class="score-layout"><section><div class="card"><div class="score-head"><div><span class="eyebrow" style="color:#b5cc9e">${editable?'TU TARJETA':esc(user(r.userId).name)}</span><h3 style="margin-top:6px">${s.played} de 18 hoyos registrados</h3></div><div class="info"><span><strong>${s.points}</strong><small style="display:block;font-size:9px">PTS STABLEFORD</small></span><span><strong>${r.playingHandicap}</strong><small style="display:block;font-size:9px">HCP JUEGO</small></span></div></div><div class="hole-picker">${r.scores.map((x,j)=>`<button class="hole-btn ${x!==null?'done':''} ${hole===j+1?'active':''}" data-action="select-hole" data-hole="${j+1}" aria-label="Hoyo ${j+1}${x!==null?', '+x+' golpes':''}">${String(j+1).padStart(2,'0')}${x!==null?`<span class="under">${s.pts[j]} pts</span>`:''}</button>`).join('')}</div><div class="hole-focus"><div class="hole-kicker">${editable?'¿Cómo ha ido?':'Así va la vuelta'}</div><h2>Hoyo ${hole}</h2><div class="hole-tags"><span>PAR <b>${r.course.pars[i]}</b></span><span>SI <b>${r.course.si[i]}</b></span><span><b>${r.course.meters[i]}</b> m</span><span>RECIBES <b>${received>0?'+':''}${received}</b></span></div>${editable?`<div class="stroke-control"><button class="stepper" data-action="score-minus" aria-label="Restar un golpe">−</button><div class="stroke-value" id="stroke-value">${draftScore}</div><button class="stepper" data-action="score-plus" aria-label="Sumar un golpe">+</button></div><div class="points-preview" id="point-preview"><b>${preview}</b> puntos Stableford netos</div><div class="score-actions">${btn('Levantar bola · 0 pts','score-x','outline')}${btn((hole===18?'Guardar último hoyo':'Guardar · Hoyo '+(hole+1))+' '+ico('arrow'),'save-hole')}</div><div style="margin-top:15px">${btn('Borrar anotación','clear-hole','ghost small')}</div><p class="small-text muted" style="margin-top:12px">Incluye los golpes de penalización en el total.</p>`:`<div class="stroke-control"><div class="stroke-value">${r.scores[i]??'—'}</div></div><div class="points-preview">${s.pts[i]===null?'Hoyo aún sin registrar':`<b>${s.pts[i]}</b> puntos Stableford netos`}</div>`}</div></div><div class="round-status">${pill(r)}<span class="muted">HCP índice ${r.hi} → campo ${r.courseHandicap} → juego ${r.playingHandicap} (${r.allowance} %)</span></div>${r.validationNote?`<div class="note warning">Revisión: ${esc(r.validationNote)}</div>`:''}${editable?`<div class="row justify wrap">${btn('Cancelar vuelta','cancel-round','ghost small')}${btn(ico('check')+'Enviar tarjeta al marcador','submit-round','primary',s.played<18||queue.length?'disabled':'')}</div>`:canValidate?`<div class="note">Revisa los 18 hoyos con el jugador. Al validar, su mejor resultado del mes se incorporará al ranking.</div><div class="row">${btn('Devolver para corregir','reject-round','outline')}${btn(ico('check')+'Validar vuelta','validate-round')}</div>`:own&&r.status==='rejected'?btn('Corregir tarjeta','reopen-round'):''}<div class="spacer"></div><details class="card full-card"><summary>Ver tarjeta completa · 18 hoyos</summary><div class="table-wrap"><table class="score-table"><thead><tr><th>Hoyo</th><th>Par</th><th>SI</th><th>Recibe</th><th>Golpes</th><th>PTS</th></tr></thead><tbody>${r.scores.map((x,j)=>`<tr class="${hole===j+1?'active':''}" data-action="select-hole" data-hole="${j+1}"><td>${j+1}</td><td>${r.course.pars[j]}</td><td>${r.course.si[j]}</td><td>${Golf.strokes(r.playingHandicap,r.course.si[j])}</td><td>${x??'—'}</td><td class="point">${s.pts[j]??'—'}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="4">Total · ${s.played}/18</td><td>${s.gross??'X'}</td><td class="point">${s.points}</td></tr></tfoot></table></div></details></section><aside class="score-side"><div class="card card-pad"><div class="section-head"><h3>En el tee</h3>${r.status==='live'?'<span class="live-pill"><span class="dot live"></span>LIVE</span>':pill(r)}</div><div class="round-owner">${avatar(user(r.userId),'lg')}<span><b>${esc(user(r.userId).name)}</b><small>HCP ${r.hi} · ${esc(r.course.tee)}</small><small>Marcador: ${esc(user(r.markerId).name)}</small></span></div><div class="score-total"><span><b>${s.front}</b><small>IDA · PTS</small></span><span><b>${s.back}</b><small>VUELTA · PTS</small></span><span><b>${s.points}</b><small>TOTAL</small></span></div>${!own?`<div class="spacer"></div>${btn((S.me.follows||[]).includes(r.userId)?ico('check')+'Siguiendo al jugador':ico('bell')+'Seguir al jugador','follow','outline full',`data-id="${r.userId}"`)}`:''}</div><div class="card card-pad"><h3>El pulso de la vuelta</h3>${S.events.filter(e=>e.roundId===r.id).slice(0,7).map(activity).join('')||'<p class="small-text muted">El primer hoyo está por llegar.</p>'}</div><div class="note">${r.status==='live'?'Resultado provisional. Los puntos cuentan en liga después de completar los 18 hoyos y validar la tarjeta.':'Solo la mejor vuelta validada de este mes suma en la jornada.'}</div></aside></div>`}
function modal(title,html,wide=false){modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Cerrar">${ico('close')}</button></div><div class="modal-body">${html}</div></section></div>`;setTimeout(()=>$('.modal input:not([type=hidden]), .modal select, .modal button')?.focus(),20)}
function closeModal(){$('#modal-root').innerHTML='';modalFocus?.focus?.({preventScroll:true})}
function errorForm(form,e){const box=form.querySelector('.error-text');if(box)box.textContent=e.message;else toast(e.message,true)}
function renderAuth(){const setup=bootstrap?.setupRequired,reg=authMode==='register';$('#app').innerHTML=`<div class="auth-screen"><aside class="auth-visual">${brand()}<div class="copy"><span class="eyebrow" style="color:#d2e697">LA LIGA DE LOS 30</span><h1>El golf es mejor<br>con los tuyos.</h1><p>12 jornadas, campos por descubrir y un grupo con muchas historias que contar.</p></div><span class="eyebrow" style="z-index:1;color:#c5d7b1">CADA HOYO CUENTA.</span></aside><section class="auth-content"><div class="auth-form"><h2>${setup?'Abrimos el clubhouse.':reg?'Tu sitio en el grupo.':'Qué bueno verte.'}</h2><p>${setup?'Crea tu cuenta de administrador. La clave de configuración aparece en la consola al arrancar el servidor.':reg?'Usa el código que te ha compartido el administrador.':'Tu liga, tu gente y tu próxima vuelta, aquí.'}</p>${!setup?`<div class="tabs"><button data-action="auth-mode" data-mode="login" class="${!reg?'active':''}">Entrar</button><button data-action="auth-mode" data-mode="register" class="${reg?'active':''}">Unirme a la liga</button></div>`:''}<form id="auth-form"><div class="error-text" role="alert"></div>${setup||reg?'<label>Tu nombre<input name="name" autocomplete="name" placeholder="¿Cómo te llama el grupo?" required maxlength="60"></label>':''}<label>Email<input name="email" type="email" autocomplete="email" placeholder="tu@email.com" required maxlength="200"></label><label>Contraseña<input name="password" type="password" autocomplete="${reg||setup?'new-password':'current-password'}" minlength="${reg||setup?10:1}" maxlength="128" required placeholder="${reg||setup?'Al menos 10 caracteres':'Tu contraseña'}"></label>${setup||reg?'<label>Índice de hándicap<input name="hi" type="number" step="0.1" min="-10" max="54" value="18" required></label>':''}${setup?'<label>Clave de configuración del servidor<input name="setupToken" required autocomplete="off"></label>':reg?'<label>Código de invitación<input name="inviteCode" required placeholder="El código privado de tu liga" autocapitalize="characters"></label>':''}<button type="submit" class="btn primary full">${setup?'Crear mi liga':reg?'Unirme al grupo':'Entrar al clubhouse'} ${ico('arrow')}</button></form><p class="auth-foot">Liga privada · 30 jugadores · 12 jornadas</p><div class="auth-demo"><p>¿Quieres ver cómo funciona antes de empezar?</p>${btn('Explorar la demo '+ico('arrow'),'demo','outline full')}</div></div></section></div>`}
function startRound(courseId){const current=activeRound();if(current){roundId=current.id;view='score';selectHole(current.currentHole||1);renderApp();return}const courses=S.courses.filter(c=>c.verified),markers=S.users.filter(u=>u.active&&u.id!==S.me.id);if(!courses.length){modal('Primero, vuestro campo.',`<p class="muted">Necesitáis al menos un campo con barras verificadas para calcular bien los puntos.</p><div class="modal-actions">${btn('Añadir campo','add-course')}</div>`);return}if(!markers.length){modal('Jugar es cosa de dos.',`<p class="muted">Invita al menos a otro jugador para que pueda ser tu marcador y validar tu tarjeta.</p><div class="modal-actions">${btn('Invitar al grupo','invite')}</div>`);return}if(!S.me.hiVerified){modal('Falta confirmar tu hándicap.',`<p class="muted">El administrador debe revisar tu índice ${S.me.hi} antes de tu primera salida o después de un cambio.</p>`);return}
 wizard={step:0,courseId:courses.some(c=>c.id===courseId)?courseId:courses[0].id,markerId:markers[0].id,date:S.today,search:''};renderWizard();
}
function updateHandicapPreview(){const c=S.courses.find(c=>c.id===$('#start-course')?.value);if(!c)return;const h=Golf.handicap(S.me.hi,c,S.settings.allowance);$('#handicap-preview').innerHTML=`Índice <b>${S.me.hi}</b> → Hándicap campo <b>${h.course}</b> → Hándicap juego <b>${h.playing}</b><br><small>Slope ${c.slope} · Valor ${c.rating} · Par ${c.pars.reduce((a,b)=>a+b,0)} · Aplicación ${S.settings.allowance} % al valor sin redondear.</small>`}
function courseForm(){modal('Vuestro siguiente campo.',`<form id="course-form"><div class="error-text" role="alert"></div><div class="form-grid"><label>Nombre del campo<input name="name" required maxlength="100"></label><label>Ciudad / zona<input name="city" maxlength="100"></label><label>Barras de salida<input name="tee" placeholder="Amarillas, rojas, blancas…" required maxlength="60"></label><label>Fuente de los datos<input name="source" placeholder="Tarjeta del club / enlace / fecha" required maxlength="400"></label><label>Slope<input name="slope" type="number" min="55" max="155" placeholder="128" required></label><label>Valor de campo (Course Rating)<input name="rating" type="number" min="40" max="90" step="0.1" placeholder="71.8" required></label></div><div class="note warning">Copia los datos oficiales para estas barras. Cada SI del 1 al 18 debe aparecer una vez. No se precargan valores para evitar una tarjeta incorrecta.</div><div class="row justify" style="margin-bottom:12px"><h3>Tarjeta de 18 hoyos</h3>${btn('Importar JSON','import-course','outline small')}</div><div class="table-wrap"><table class="course-input-table"><thead><tr><th>Hoyo</th><th>Par</th><th>Índice SI</th><th>Metros</th></tr></thead><tbody>${Array.from({length:18},(_,i)=>`<tr><td>${i+1}</td><td><input type="number" name="par${i}" min="3" max="6" required aria-label="Par hoyo ${i+1}"></td><td><input type="number" name="si${i}" min="1" max="18" required aria-label="SI hoyo ${i+1}"></td><td><input type="number" name="m${i}" min="30" max="900" required aria-label="Metros hoyo ${i+1}"></td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="btn primary">${S.me.role==='admin'?'Confirmar datos y guardar':'Proponer campo al administrador'}</button></div></form>`,true)}
function rules(){modal('Así jugamos.',`<div class="help-list"><div><b>01 · Una jornada por mes</b><p>12 meses en la temporada ${S.settings.year}. Cada uno juega en el campo que quiera. Formato de 18 hoyos; todas las barras deben tener slope, valor de campo y tarjeta comprobados.</p></div><div><b>02 · Stableford neto</b><p>HCP campo = índice × slope / 113 + (valor de campo − par). El porcentaje de ${S.settings.allowance} % se aplica al valor sin redondear y luego se redondea al entero más cercano (mitades hacia arriba). Se reparten los golpes según SI.</p></div><div><b>03 · Cada hoyo cuenta</b><p>Par neto: 2 puntos; birdie neto: 3; eagle neto: 4; bogey neto: 1; doble bogey neto o más: 0. «Levantar bola» suma 0. Un hoyo sin registrar queda pendiente.</p></div><div><b>04 · La mejor vuelta del mes</b><p>Solo cuenta la vuelta con más puntos validada de ese mes. La general suma las ${S.settings.bestMonths} mejores jornadas. Un mes sin resultado suma 0. Los empates comparten posición; el orden alfabético solo ordena la pantalla.</p></div><div><b>05 · Un marcador, confianza para todos</b><p>El jugador introduce sus golpes, incluidas penalizaciones. Su marcador u otro administrador revisa la tarjeta. No se permite autovalidar; una tarjeta validada se bloquea. Si hay errores, se devuelve antes de validar.</p></div><div><b>06 · En directo, con cobertura</b><p>El registro de un hoyo se comparte con toda la liga. Sin cobertura se guarda en el dispositivo y se sincroniza al abrir la app con conexión; todavía no es visible para los demás.</p></div><div><b>07 · Liga privada</b><p>Todos los miembros ven tarjetas, perfiles y chats de partidas. El índice es declarado y confirmado por el administrador. La app no recalcula el hándicap oficial ni envía resultados a la federación. Las reglas locales las acuerda vuestro comité.</p></div></div>`,true)}
async function navigate(v){search='';view=v;roundId=v==='score'?roundId:null;location.hash=v;if(v==='chat')await loadMessages();renderApp();window.scrollTo({top:0,behavior:'instant'})}
function selectHole(n){hole=Math.max(1,Math.min(18,n));const r=S.rounds.find(r=>r.id===roundId);draftScore=typeof r?.scores[hole-1]==='number'?r.scores[hole-1]:r?.course.pars[hole-1]||4}
function changeDraft(delta){draftScore=Math.max(1,Math.min(30,draftScore+delta));const r=S.rounds.find(r=>r.id===roundId),received=Golf.strokes(r.playingHandicap,r.course.si[hole-1]);$('#stroke-value').textContent=draftScore;$('#point-preview').innerHTML=`<b>${Golf.points(draftScore,r.course.pars[hole-1],received)}</b> puntos Stableford netos`}
function recordScore(score){const r=S.rounds.find(r=>r.id===roundId);if(!r||r.userId!==S.me.id||r.status!=='live')return;if(conflict){resolveConflict();return}const op={roundId:r.id,hole,score,revision:r.revision,operationId:crypto.randomUUID?crypto.randomUUID():'op-'+Date.now()+Math.random()};queue.push(op);r.scores[hole-1]=score;r.revision++;r.currentHole=Math.min(18,r.scores.findIndex(x=>x===null)+1||18);persistQueue();const finished=hole===18&&score!==null&&!r.scores.includes(null);if(score!==null)selectHole(Math.min(18,hole+1));renderApp();if(finished)toast('18 hoyos completos. Revisa y envía la tarjeta a tu marcador.');void syncQueue()}
async function syncQueue(){if(syncing||conflict||!S||(!DEMO&&!navigator.onLine))return;syncing=true;try{while(queue.length){const op=queue[0];let r;try{r=await api('/api/rounds/'+op.roundId+'/hole','POST',{hole:op.hole,score:op.score,revision:op.revision,operationId:op.operationId})}catch(e){if(e.status===409){conflict={server:e.data?.round||null,roundId:op.roundId,message:e.message};toast('Un cambio en otro dispositivo requiere revisión.',true);renderApp()}else if(e.status&&e.status!==401){conflict={server:null,roundId:op.roundId,message:e.message};toast(e.message,true);renderApp()}break}queue.shift();persistQueue();const i=S.rounds.findIndex(x=>x.id===r.id);if(i>=0)S.rounds[i]=r;overlayPending()}if(!queue.length){await loadState(false);renderApp()}}finally{syncing=false}}
function resolveConflict(){if(!conflict)return;const pending=queue.filter(o=>o.roundId===conflict.roundId);modal('Revisar golpes pendientes.',`<p class="muted small-text">${esc(conflict.message)}</p><div class="note warning">Tus anotaciones pendientes: ${pending.map(o=>'hoyo '+o.hole+': '+(o.score??'borrar')).join(' · ')}. No se sobrescribirá la tarjeta sin tu decisión.</div><div class="modal-actions wrap">${btn('Conservar tarjeta del servidor','discard-queue','outline')}${conflict.server?.status==='live'?btn('Reaplicar mis anotaciones','rebase-queue'):''}</div>`)}
async function roundAction(action,body={}){if(queue.length){toast('Espera a que se sincronicen los golpes.',true);return}const r=await api('/api/rounds/'+roundId+'/'+action,'POST',body);closeModal();await loadState(false);if(r.status==='live')selectHole(r.currentHole||1);renderApp();toast({submit:'Tarjeta enviada a tu marcador.',validate:'¡Vuelta validada! Ranking actualizado.',reject:'Tarjeta devuelta para corregir.',cancel:'Vuelta cancelada.',reopen:'Tarjeta abierta para corregir.'}[action])}
function confirmAction(title,text,action){modal(title,`<p class="muted">${text}</p><div class="modal-actions">${btn('Volver','close-modal','outline')}${btn('Confirmar',action)}</div>`)}
async function uploadFile(file,profile=false){if(!file)return null;let candidate=file;if(file.type.startsWith('image/')){try{const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas'),scale=Math.min(1,(profile?512:1600)/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.86));bitmap.close();if(blob)candidate=new File([blob],profile?'avatar.jpg':'foto.jpg',{type:'image/jpeg'})}catch{}}
 if(!/^(image\/(jpeg|png|webp)|video\/(mp4|webm|quicktime))$/.test(candidate.type))throw Error('Elige una foto JPG/PNG/WebP o un clip MP4/MOV/WebM.');if(profile&&!candidate.type.startsWith('image/'))throw Error('El perfil necesita una foto.');if(candidate.size>(candidate.type.startsWith('image/')?8:25)*1024*1024)throw Error('La foto supera 8 MB o el vídeo supera 25 MB. Usa un clip más corto.');
 toast('Subiendo '+(profile?'tu foto…':'el archivo…'));if(DEMO)return {...await Demo.upload(candidate),name:candidate.name};const res=await fetch('/api/media',{method:'POST',headers:{'Content-Type':candidate.type},credentials:'same-origin',body:candidate});const data=await res.json();if(!res.ok)throw Error(data.error);return {...data,name:candidate.name};
}
function pickFile(accept,capture,callback){const input=document.createElement('input');input.type='file';input.accept=accept;if(capture)input.setAttribute('capture','environment');input.onchange=async()=>{try{await callback(input.files[0])}catch(e){toast(e.message,true)}};input.click()}
function download(text,name,mime='text/plain'){const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado. Compártelo con el grupo.')}catch{modal('Comparte con el grupo.',`<textarea readonly>${esc(text)}</textarea><p class="small-text muted">Mantén pulsado o selecciona el texto para copiar.</p>`)}}
async function enableNotifications(){if(!('Notification'in window)||!('serviceWorker'in navigator)||!window.isSecureContext){modal('Avisos en tu móvil.',`<p class="muted">Los avisos necesitan una dirección HTTPS y un navegador compatible. En iPhone, instala primero la PWA en la pantalla de inicio y ábrela desde ahí.</p>`);return}if(DEMO){toast('Los avisos entre usuarios se activan con el servidor de la liga.');return}const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Puedes permitir los avisos desde los ajustes del navegador.');return}const sw=await navigator.serviceWorker.ready;if(S.pushPublicKey&&'PushManager'in window){const bytes=Uint8Array.from(atob(S.pushPublicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0)),sub=await sw.pushManager.getSubscription()||await sw.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});await api('/api/push','POST',sub.toJSON());toast('Avisos activados. Sigue a los jugadores que te interesan.')}else toast('Avisos con la app abierta activados. Para recibirlos cerrada, configura Web Push.');}
async function disableNotifications(){if(!DEMO&&'serviceWorker'in navigator){const sw=await navigator.serviceWorker.ready,sub=await sw.pushManager?.getSubscription();if(sub){await api('/api/push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe()}}toast('Suscripción a avisos de este dispositivo desactivada.')}
function userEditor(id){const u=user(id);modal('Revisar a '+esc(u.name),`<form id="verify-form" data-id="${u.id}"><div class="error-text"></div><label>Índice de hándicap<input name="hi" type="number" min="-10" max="54" step="0.1" value="${u.hi}" required></label><label class="inline-check"><input name="hiVerified" type="checkbox" checked>He comprobado este índice con el jugador</label><label class="inline-check"><input name="active" type="checkbox" ${u.active?'checked':''} ${id===S.me.id?'disabled':''}>Cuenta activa</label><label>Restablecer contraseña (opcional)<input type="password" name="password" minlength="10" maxlength="128" autocomplete="new-password" placeholder="Dejar vacío para conservarla"></label><p class="small-text muted">Si cambias la contraseña, comunica al jugador la nueva por vuestro canal habitual. La app no envía emails.</p><div class="modal-actions"><button class="btn primary">Guardar revisión</button></div></form>`)}
let welcomeStage='',wizard=null;
function renderWelcome(){
 welcomeStage='welcome';closeModal();
 $('#app').innerHTML=`<main class="welcome"><header>${brand()}<span class="welcome-tag">TU LIGA. TU GENTE.</span></header><div class="welcome-grid"><section class="welcome-copy"><span class="eyebrow">30 AMIGOS · 12 MESES · MUCHO GOLF</span><h1>El golf es mejor<br>con los tuyos<span>.</span></h1><p>Juega donde quieras. Comparte cada hoyo.<br>Que el pique dure todo el año.</p><div class="welcome-actions">${btn('Probar el recorrido '+ico('arrow'),'journey-demo','primary full')}${!window.CLUBHOUSE_STATIC?btn('Entrar en mi liga','journey-login','outline full'):''}</div><small class="welcome-caption">Vista previa sin registro · Con jugadores y campos ficticios</small><div class="welcome-features"><span>${ico('flag')} Anota fácil</span><span>${ico('live')} Sigue en directo</span><span>${ico('trophy')} Compite en tu liga</span></div></section><section class="welcome-scene" aria-label="Vista de una tarjeta de golf"><div class="scene-orbit"></div><div class="preview-card"><div class="preview-top"><span>MI VUELTA</span><span class="live-pill"><span class="dot"></span> EN JUEGO</span></div><h2>Hoyo 7</h2><p>PAR 4 <span>·</span> 354 m</p><div class="preview-score"><span>−</span><b>5</b><span>+</span></div><div class="preview-points">2 puntos Stableford</div><div class="preview-save">Guardar y seguir ${ico('arrow')}</div><small>Nosotros hacemos las cuentas.</small></div><div class="scene-note">${ico('trophy')} Tu campo cambia. Tu liga sigue.</div></section></div><footer>Clubhouse · Cada hoyo cuenta.</footer></main>`;
}
function renderDemoProfile(){
 welcomeStage='profile';Demo.init();const me=Demo.init().users.find(u=>u.id==='demo-0');
 $('#app').innerHTML=`<main class="onboarding"><header><button data-action="journey-back" class="icon-btn" aria-label="Volver">${ico('back')}</button>${brand()}<span class="badge">VISTA PREVIA</span></header><section class="onboarding-panel"><span class="eyebrow">01 / 02 · TU PERFIL</span><h1>¿Cómo te conoce<br>el grupo?</h1><p>Solo lo esencial para empezar. Después puedes añadir tu foto y personalizar tu perfil.</p><form id="demo-profile-form"><div class="error-text" role="alert"></div><label>Tu nombre<input name="name" autocomplete="given-name" maxlength="60" required value="${esc(me.name)}"></label><label>Índice de hándicap<input name="hi" type="number" min="-10" max="54" step="0.1" required value="${me.hi}"><small>Tu índice actual, por ejemplo 18,4. Si es +2, introduce −2.</small></label><label>Tu club o ciudad <span class="muted">(opcional)</span><input name="club" maxlength="100" value="${esc(me.club)}" placeholder="¿Dónde sueles jugar?"></label><button class="btn primary full" type="submit">Continuar ${ico('arrow')}</button></form><p class="privacy-caption">Es una prueba local. No se crea una cuenta ni se envían tus datos.</p></section></main>`;
}
function renderDemoReady(){welcomeStage='ready';$('#app').innerHTML=`<main class="onboarding"><header>${brand()}<span class="badge">VISTA PREVIA</span></header><section class="onboarding-panel"><span class="eyebrow">02 / 02 · TU LIGA</span><h1>Ya estás en el club<span class="hello-dot"></span></h1><p>Así sería entrar en vuestra liga privada.</p><div class="ready-league"><span class="league-icon">${ico('trophy')}</span><h2>La Liga de los 30</h2><p>30 jugadores · 12 jornadas</p><div class="avatar-stack">${Demo.init().users.slice(0,5).map(u=>avatar(u)).join('')}<span>+25</span></div></div><ol class="journey-list"><li><b>Juega en cualquier campo</b><span>Elige las barras y tu marcador.</span></li><li><b>Anota los golpes de cada hoyo</b><span>Los puntos se calculan automáticamente.</span></li><li><b>Suma tu mejor vuelta del mes</b><span>Tu marcador la valida y entra en la liga.</span></li></ol>${btn('Entrar al club '+ico('arrow'),'journey-finish','primary full')}<small class="privacy-caption">En la liga real te unirás con el código de invitación del grupo.</small></section></main>`}
function renderWizard(){
 const c=S.courses.find(c=>c.id===wizard.courseId),h=Golf.handicap(S.me.hi,c,S.settings.allowance),marker=user(wizard.markerId);
 const titles=['¿Dónde jugamos?','¿Quién te acompaña?','Todo listo para el tee.'];
 modal('Nueva vuelta',`<div class="wizard-progress">${['Campo','Marcador','Empezar'].map((t,i)=>`<span class="${i<=wizard.step?'active':''}"><b>${i+1}</b>${t}</span>`).join('')}</div><h2 class="wizard-title">${titles[wizard.step]}</h2>${wizard.step===0?`<p class="muted">Elige un campo y sus barras de salida.</p><label class="course-search-label">Buscar campo<input type="search" id="course-search" placeholder="Nombre o ciudad…" value="${esc(wizard.search||'')}"></label><div class="course-options">${S.courses.filter(c=>c.verified).map(c=>`<button class="course-option ${wizard.courseId===c.id?'selected':''}" data-action="wizard-course" data-id="${c.id}" data-search="${esc((c.name+' '+c.city).toLowerCase())}"><span class="course-option-icon">${ico('pin')}</span><span><b>${esc(c.name)}</b><small>${esc(c.city)}</small><small>${esc(c.tee)} · Par ${c.pars.reduce((a,b)=>a+b,0)}</small></span>${ico(wizard.courseId===c.id?'check':'plus')}</button>`).join('')}</div><p id="course-search-empty" class="muted" hidden>No hay campos que coincidan.</p>`:wizard.step===1?`<p class="muted">Tu marcador revisará los golpes al terminar.</p><label>Marcador<select id="wizard-marker">${S.users.filter(u=>u.active&&u.id!==S.me.id).map(u=>`<option value="${u.id}" ${wizard.markerId===u.id?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><label>Fecha<input type="date" id="wizard-date" value="${wizard.date}" max="${S.today}" required></label><div class="note">${ico('check')} Tu marcador podrá validar la tarjeta desde su cuenta.</div>`:`<div class="round-review"><div><small>CAMPO Y BARRAS</small><h3>${esc(c.name)}</h3><p>${esc(c.tee)} · 18 hoyos</p></div><div class="review-numbers"><span><b>${S.me.hi}</b><small>Tu índice</small></span>${ico('arrow')}<span><b>${h.playing}</b><small>HCP de juego</small></span></div><p>Marcador: <b>${esc(marker.name)}</b></p><p>Fecha: ${esc(wizard.date)}</p><details><summary>Cómo calculamos tu hándicap</summary><p>Índice × slope / 113 + valor de campo − par. Se aplica ${S.settings.allowance}% antes de redondear. Slope ${c.slope}; valor ${c.rating}; HCP campo ${h.course}.</p></details></div><form id="start-form"><input type="hidden" name="courseId" value="${c.id}"><input type="hidden" name="markerId" value="${wizard.markerId}"><input type="hidden" name="date" value="${wizard.date}"><div class="error-text" role="alert"></div><button class="btn primary full" type="submit">Empezar vuelta ${ico('arrow')}</button></form><p class="privacy-caption">${DEMO?'Vuelta de prueba guardada solo en este navegador.':'Tu grupo podrá seguir tus golpes en directo.'}</p>`}<div class="wizard-actions">${wizard.step?btn(ico('back')+'Atrás','wizard-back','ghost'):btn('Cancelar','close-modal','ghost')}${wizard.step<2?btn('Continuar '+ico('arrow'),'wizard-next'):''}</div>`);
 filterWizardCourses();if($('#course-search'))$('#course-search').value=wizard.search||'';
}
function filterWizardCourses(){let count=0;for(const el of $$('.course-option')){el.hidden=!el.dataset.search.includes((wizard.search||'').toLowerCase());if(!el.hidden)count++}if($('#course-search-empty'))$('#course-search-empty').hidden=!!count}
async function handleAction(el){const a=el.dataset.action,d=el.dataset;if(el.disabled)return;
 if(a==='journey-back'){renderWelcome();return}
 if(a==='journey-demo'){DEMO=true;renderDemoProfile();return}
 if(a==='journey-login'){welcomeStage='';localStorage.setItem('clubhouse-welcome-v2','1');DEMO=false;await boot();return}
 if(a==='journey-finish'){welcomeStage='';localStorage.setItem('clubhouse-welcome-v2','1');if(location.protocol!=='file:')history.replaceState({},'',location.pathname+'?demo=1');view='home';await boot();return}
 if(a==='restart-journey'){if(queue.length){toast('Espera a que se guarden tus golpes.',true);return}source?.close();localStorage.removeItem('clubhouse-welcome-v2');renderWelcome();return}
 if(a==='wizard-course'){wizard.courseId=d.id;renderWizard();return}
 if(a==='wizard-back'){if(wizard.step===1){wizard.markerId=$('#wizard-marker').value;wizard.date=$('#wizard-date').value}wizard.step--;renderWizard();return}
 if(a==='wizard-next'){if(wizard.step===1){if(!$('#wizard-date').reportValidity())return;wizard.markerId=$('#wizard-marker').value;wizard.date=$('#wizard-date').value}wizard.step++;renderWizard();return}
 if(a==='retry'){await boot();return}if(a==='demo'){DEMO=true;renderDemoProfile();return}
 if(a==='auth-mode'){authMode=d.mode;renderAuth();return}if(a==='close-modal'){closeModal();return}
 if(a==='nav'){closeModal();await navigate(d.view);return}if(a==='home'){await navigate('home');return}
 if(a==='round'){closeModal();roundId=d.id;view='score';selectHole(S.rounds.find(r=>r.id===roundId)?.currentHole||1);renderApp();window.scrollTo({top:0,behavior:'instant'});return}
 if(a==='my-round'){const r=activeRound();if(r){roundId=r.id;view='score';selectHole(r.currentHole||1);renderApp()}else startRound();return}
 if(a==='new-round'){startRound(d.course);return}if(a==='rules'){rules();return}if(a==='add-course'){courseForm();return}
 if(a==='rank-mode'){rankMode=d.mode;renderApp();return}if(a==='rank-month'){closeModal();rankMode='monthly';rankMonth=Number(d.month);view='ranking';renderApp();return}
 if(a==='select-hole'){selectHole(Number(d.hole));renderApp();return}if(a==='score-minus'){changeDraft(-1);return}if(a==='score-plus'){changeDraft(1);return}
 if(a==='save-hole'){recordScore(draftScore);return}if(a==='score-x'){recordScore('X');return}if(a==='clear-hole'){recordScore(null);return}
 if(a==='round-chat'){closeModal();room=d.id;await navigate('chat');return}
 if(a==='chat-room'){attachment=null;room=d.room;await loadMessages();renderApp();return}
 if(a==='older-messages'){const prev=await api('/api/messages?room='+encodeURIComponent(room)+'&before='+encodeURIComponent(messages[0].createdAt));messages=[...prev.messages,...messages];renderApp();return}
 if(a==='react'){await api('/api/messages/'+d.id+'/react','POST',{});await loadMessages();renderApp();return}
 if(a==='delete-message'){confirmAction('¿Eliminar este mensaje?','Se quitará de la conversación para todo el grupo.','confirm-delete-message');$('.modal').dataset.messageId=d.id;return}
 if(a==='confirm-delete-message'){const id=$('.modal').dataset.messageId;await api('/api/messages/'+id+'/delete','POST',{});closeModal();await loadMessages();renderApp();return}
 if(a==='attach-photo'||a==='attach-video'){if(!DEMO&&!navigator.onLine){toast('Los adjuntos necesitan conexión. Tus golpes sí se guardan sin cobertura.');return}pickFile(a==='attach-photo'?'image/jpeg,image/png,image/webp':'video/mp4,video/webm,video/quicktime',true,async f=>{if(f){attachment=await uploadFile(f);renderApp();toast('Adjunto listo para enviar.')}});return}
 if(a==='remove-attachment'){attachment=null;renderApp();return}
 if(a==='avatar-upload'){pickFile('image/jpeg,image/png,image/webp',false,async f=>{if(f){const m=await uploadFile(f,true);await api('/api/profile','PATCH',{avatar:m.id});await loadState();toast('Foto de perfil actualizada.')}});return}
 if(a==='follow'){const ids=new Set(S.me.follows||[]);ids.has(d.id)?ids.delete(d.id):ids.add(d.id);await api('/api/profile','PATCH',{follows:[...ids]});await loadState();toast(ids.has(d.id)?'Siguiendo a '+user(d.id).name+'.':'Has dejado de seguir a '+user(d.id).name+'.');return}
 if(a==='player'){const u=user(d.id),rank=annual().find(r=>r.user.id===u.id);modal(esc(u.name),`<div style="text-align:center">${avatar(u,'xl')}<p class="muted" style="margin:14px 0">${esc(u.bio||'Cada hoyo cuenta.')}</p><p class="small-text">${esc(u.club||'')} · HCP ${u.hi} · ${rank?.total||0} pts en liga</p><div class="spacer"></div>${u.id!==S.me.id?btn((S.me.follows||[]).includes(u.id)?'Dejar de seguir':'Seguir al jugador','follow','primary',`data-id="${u.id}"`):btn('Editar mi perfil','nav','primary','data-view="profile"')}</div>`);return}
 if(a==='submit-round'){confirmAction('¿Tarjeta completa?','Comprueba los golpes con tu marcador. Se enviará para revisión y quedará bloqueada mientras se valida.','confirm-submit');return}
 if(a==='confirm-submit'){await roundAction('submit');return}if(a==='validate-round'){confirmAction('Validar esta vuelta.','Confirma que has revisado los 18 hoyos. La tarjeta quedará cerrada y sus puntos podrán entrar en la clasificación.','confirm-validate');return}if(a==='confirm-validate'){await roundAction('validate');return}
 if(a==='reject-round'){modal('Qué hay que revisar.',`<form id="reject-form"><label>Motivo de devolución<textarea name="note" required maxlength="250" placeholder="Por ejemplo: revisar el hoyo 7…"></textarea></label><div class="modal-actions"><button class="btn primary">Devolver al jugador</button></div></form>`);return}
 if(a==='reopen-round'){await roundAction('reopen');return}if(a==='cancel-round'){confirmAction('¿Cancelar esta vuelta?','Se conservará como cancelada y no contará para la liga.','confirm-cancel');return}if(a==='confirm-cancel'){await roundAction('cancel');return}
 if(a==='resolve-conflict'){resolveConflict();return}if(a==='discard-queue'){queue=queue.filter(o=>o.roundId!==conflict.roundId);persistQueue();conflict=null;closeModal();await loadState();void syncQueue();return}
 if(a==='rebase-queue'){const ops=queue.filter(o=>o.roundId===conflict.roundId),base=conflict.server.revision;ops.forEach((o,i)=>{o.revision=base+i;o.operationId=crypto.randomUUID?crypto.randomUUID():'op-'+Date.now()+'-'+i});conflict=null;persistQueue();closeModal();await syncQueue();return}
 if(a==='course-details'){const c=S.courses.find(c=>c.id===d.id);modal(esc(c.name)+' · '+esc(c.tee),`<p class="small-text muted">${esc(c.city)} · Slope ${c.slope} · Valor ${c.rating}</p><div class="note">Fuente: ${esc(c.source||'No indicada')}</div><table class="score-table"><thead><tr><th>Hoyo</th><th>Par</th><th>SI</th><th>Metros</th></tr></thead><tbody>${c.pars.map((p,i)=>`<tr><td>${i+1}</td><td>${p}</td><td>${c.si[i]}</td><td>${c.meters[i]}</td></tr>`).join('')}</tbody></table>${!c.verified&&S.me.role==='admin'?`<div class="modal-actions">${btn('Confirmar datos y verificar','approve-course','primary',`data-id="${c.id}"`)}</div>`:''}`);return}
 if(a==='approve-course'){await api('/api/courses/'+d.id+'/approve','POST',{});closeModal();await loadState();toast('Barras verificadas. Ya se puede jugar.');return}
 if(a==='import-course'){pickFile('application/json,.json',false,async f=>{if(!f)return;const c=JSON.parse(await f.text());Golf.validateCourse(c);const form=$('#course-form');for(const n of ['name','city','tee','source','slope','rating'])if(c[n]!==undefined)form.elements[n].value=c[n];c.pars.forEach((p,i)=>{form.elements['par'+i].value=p;form.elements['si'+i].value=c.si[i];form.elements['m'+i].value=c.meters[i]});toast('Tarjeta importada. Revisa los datos antes de guardar.')});return}
 if(a==='verify-user'){userEditor(d.id);return}if(a==='invite'){if(!S.admin){toast('Pide el código al administrador.');return}await copy(`${S.settings.name}\n${DEMO?'[Dirección de vuestra app]':location.origin}\nCódigo de invitación: ${S.admin.inviteCode}\nEntra y pulsa «Unirme a la liga».`);return}
 if(a==='rotate-invite'){await api('/api/admin/settings','PATCH',{rotateInvite:true});await loadState();toast('Nuevo código creado. El anterior ya no sirve.');return}
 if(a==='admin-export'){if(DEMO){download(JSON.stringify({settings:S.settings,users:S.users,rounds:S.rounds,courses:S.courses},null,2),'clubhouse-demo.json','application/json');return}const res=await fetch('/api/export');if(!res.ok)throw Error('No se pudo exportar.');download(JSON.stringify(await res.json(),null,2),'clubhouse-datos.json','application/json');return}
 if(a==='export-ranking'){const rows=Golf.ranking(S.users,S.rounds,S.settings,rankMode==='monthly'?rankMonth:null);const cell=v=>'"'+String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';const csv=[['Posición','Jugador','Índice',...months,'Total'],...rows.map(r=>[r.entries?r.rank:'',r.user.name,r.user.hi,...r.monthly,r.total])].map(r=>r.map(cell).join(';')).join('\r\n');download('\ufeff'+csv,'clubhouse-clasificacion-'+S.settings.year+'.csv','text/csv;charset=utf-8');return}
 if(a==='enable-notifications'){await enableNotifications();return}if(a==='disable-notifications'){await disableNotifications();return}
 if(a==='notifications'){modal('El pulso del club.',`<p class="small-text muted" style="margin-bottom:15px">Sigue jugadores para recibir sus hoyos. El chat puede avisarte si lo activas en tu perfil.</p>${S.events.slice(0,30).map(activity).join('')||empty('Todavía en calma','Las novedades de la liga aparecerán aquí.')}<div class="modal-actions">${btn('Configurar avisos','nav','primary','data-view="profile"')}</div>`);return}
 if(a==='install'){if(installPrompt){await installPrompt.prompt();installPrompt=null}else modal('Clubhouse en tu pantalla.',`<div class="help-list"><div><b>Android / Chrome</b><p>Abre la dirección HTTPS de vuestra liga. Menú ⋮ → «Instalar aplicación» o «Añadir a pantalla de inicio».</p></div><div><b>iPhone / Safari</b><p>Compartir → «Añadir a pantalla de inicio». Abre la app desde su icono y activa los avisos ahí.</p></div><div><b>En ordenador</b><p>Chrome o Edge → icono de instalación en la barra de direcciones. La demo descargada es una vista previa; la instalación requiere servir la app.</p></div></div>`);return}
 if(a==='password'){modal('Cambiar contraseña.',`<form id="password-form"><div class="error-text"></div><label>Contraseña actual<input name="current" type="password" autocomplete="current-password" required></label><label>Nueva contraseña<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><div class="modal-actions"><button class="btn primary">Guardar contraseña</button></div></form>`);return}
 if(a==='logout'){if(queue.length){toast('Sincroniza tus golpes antes de salir para conservar la tarjeta.',true);return}await disableNotifications().catch(()=>{});await api('/api/logout','POST',{});source?.close();localStorage.removeItem('clubhouse-cache-real');S=null;authMode='login';renderAuth();return}
 if(a==='demo-switch'){if(queue.length){toast('Espera a que se guarden tus golpes.',true);return}modal('Prueba otro lugar del grupo.',`<p class="small-text muted" style="margin-bottom:15px">Cambia de jugador para probar el rol de marcador. Solo Víctor administra la demo.</p><div class="people-grid">${S.users.map(u=>`<button class="row card" style="padding:10px" data-action="demo-select" data-id="${u.id}">${avatar(u)}<span class="small-text">${esc(u.name)}</span></button>`).join('')}</div>`,true);return}
 if(a==='demo-select'){await api('/demo/switch','POST',{id:d.id});closeModal();S=await api('/api/state');queue=JSON.parse(localStorage.getItem(qkey())||'[]');room='league';view='home';renderApp();return}
 if(a==='demo-exit'){if(DEMO){await api('/demo/reset','POST',{});queue=[];conflict=null;localStorage.removeItem('clubhouse-queue-demo-demo-0');view='home';localStorage.removeItem('clubhouse-welcome-v2');renderWelcome();toast('Demo reiniciada.')}else{source?.close();location.href=location.pathname}return}
 if(a==='more-menu'){modal('Todo tu clubhouse.',`<div class="nav" style="background:#f5f8f7;border-radius:12px;padding:12px">${[['calendar','calendar','Las 12 jornadas'],['courses','pin','Campos'],['profile','user','Mi perfil'],...(S.me.role==='admin'?[['admin','gear','Administrar liga']]:[])].map(([v,i,t])=>`<button data-action="nav" data-view="${v}">${ico(i)}${t}</button>`).join('')}</div><div class="modal-actions">${btn('Cómo jugamos','rules','outline')}${btn('Instalar app','install','primary')}</div>`);return}
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();handleAction(el).catch(err=>toast(err.message,true))});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!form.id?.endsWith('-form'))return;e.preventDefault();if(form.dataset.busy)return;form.dataset.busy='1';const submit=form.querySelector('[type=submit],button:not([type])');if(submit)submit.disabled=true;const data=new FormData(form),b=Object.fromEntries(data);try{
  if(form.id==='demo-profile-form'){await Demo.call('/demo/switch','POST',{id:'demo-0'});if(!b.name.trim())throw Error('Escribe tu nombre para continuar.');await Demo.call('/api/profile','PATCH',{name:b.name.trim(),hi:Number(b.hi),club:b.club.trim()});await Demo.call('/api/admin/users/demo-0','PATCH',{hiVerified:true});renderDemoReady();return}
  if(form.id==='auth-form'){const endpoint=bootstrap.setupRequired?'setup':authMode==='register'?'register':'login';if(b.hi!==undefined)b.hi=Number(b.hi);if(b.inviteCode)b.inviteCode=b.inviteCode.trim().toUpperCase();await api('/api/'+endpoint,'POST',b);await boot();return}
  if(form.id==='start-form'){const r=await api('/api/rounds','POST',b);closeModal();roundId=r.id;view='score';await loadState(false);selectHole(1);renderApp();toast('¡Buena vuelta! Tu grupo ya puede seguirte.');return}
  if(form.id==='course-form'){const c={name:b.name,city:b.city,tee:b.tee,source:b.source,slope:Number(b.slope),rating:Number(b.rating),pars:Array.from({length:18},(_,i)=>Number(b['par'+i])),si:Array.from({length:18},(_,i)=>Number(b['si'+i])),meters:Array.from({length:18},(_,i)=>Number(b['m'+i]))};Golf.validateCourse(c);await api('/api/courses','POST',c);closeModal();view='courses';await loadState();toast(S.me.role==='admin'?'Campo guardado y verificado.':'Campo propuesto al administrador.');return}
  if(form.id==='profile-form'){await api('/api/profile','PATCH',{name:b.name,hi:Number(b.hi),club:b.club,bio:b.bio,notifyChat:data.has('notifyChat')});await loadState();toast('Tu perfil ya está al día.');return}
  if(form.id==='settings-form'){await api('/api/admin/settings','PATCH',{name:b.name,year:Number(b.year),bestMonths:Number(b.bestMonths),allowance:Number(b.allowance),openMonths:data.getAll('openMonth').map(Number)});await loadState();toast('Reglamento guardado.');return}
  if(form.id==='verify-form'){const id=form.dataset.id;await api('/api/admin/users/'+id,'PATCH',{hi:Number(b.hi),hiVerified:data.has('hiVerified'),active:id===S.me.id?true:data.has('active'),...(b.password?{password:b.password}:{})});closeModal();await loadState();toast('Perfil revisado.');return}
  if(form.id==='password-form'){await api('/api/password','POST',b);closeModal();toast('Contraseña actualizada.');return}
  if(form.id==='reject-form'){await roundAction('reject',{note:b.note});return}
  if(form.id==='chat-form'){const text=(b.text||'').trim();if(!text&&!attachment)return;if(!DEMO&&!navigator.onLine)throw Error('Para enviar mensajes y adjuntos necesitas conexión.');await api('/api/messages','POST',{room,text,media:attachment?.id});attachment=null;if($('#chat-input'))$('#chat-input').value='';await loadMessages();renderApp();const m=$('#messages');if(m)m.scrollTop=m.scrollHeight;return}
 }catch(err){errorForm(form,err)}finally{delete form.dataset.busy;if(submit)submit.disabled=false}
});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){wizard.search=e.target.value;filterWizardCourses();return}if(e.target.id==='rank-search'||e.target.id==='people-search'){search=e.target.value;renderApp()}});
document.addEventListener('change',e=>{if(e.target.id==='start-course')updateHandicapPreview()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.modal'))closeModal();if(e.key==='Tab'&&$('.modal')){const els=[...$('.modal').querySelectorAll('button:not(:disabled), input:not(:disabled), select, textarea, a[href]')];if(!els.length)return;const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}if(e.key==='Enter'&&e.target.id==='chat-input'&&!e.shiftKey&&window.innerWidth>600){e.preventDefault();$('#chat-form').requestSubmit()}});
window.addEventListener('online',()=>{connected=DEMO;void syncQueue();void loadState()});window.addEventListener('offline',()=>{connected=false;renderConnection();toast('Sin cobertura. Tus golpes se guardarán en el dispositivo.')});
window.addEventListener('hashchange',()=>{if(!S||welcomeStage)return;const next=location.hash.slice(1)||'home';if(next!==view)void navigate(next)});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&S){void loadState(!['profile','admin'].includes(view));void syncQueue()}});
window.addEventListener('beforeunload',e=>{if(queue.length){e.preventDefault();e.returnValue='Hay golpes pendientes de enviar.'}});
if(location.protocol!=='file:'&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
void boot();
})();
